    java.replaceFont(result, f1, f2)
}else{
    result
}

ruleExplore.bookList:
@JSon:$..[?(@.novelName)]&&$..[?(@.novelname)]
<js>
if(baseUrl=='https://app-cdn.jjwxc.net/bookstore/getFullPage?channel=bhxs&version=3'){
list=JSON.parse(src);
for(i in list){
channelName=list[i].channelName;
blist=list[i].data;
if(blist[0]){
for(j in blist){
blist[j].channelName=channelName
}}else{blist.channelName=channelName}

}
let delIndexList = [0, 6,11,12,13]; // 要删除的序列
 if (delIndexList.length !== 0) { 
for (let i = delIndexList.length - 1; i >= 0; i--) { list.splice(delIndexList[i], 1) } }
result=JSON.stringify(list);}
else{result=result}</js>
$..[?(@.novelName)]&&$..[?(@.novelname)]

ruleSearch.lastChapter:
@js:
last=JSON.parse(java.ajax('http://android.jjwxc.net/androidapi/chapterList?novelId={{$.novelid||$.novelId}}')).chapterlist;
if(last){
last=last[last.length-1];
vip=last.isvip!=0?"🔒":'';
date=last.chapterdate;
chapter=last.chaptername;
chapterid=last.chapterid;
result=vip+chapterid+'.'+chapter+'•'+date}

ruleToc.chapterName:
$.chaptername
@js:
result=result.replace(/^\s+/,'');
vip='{{$.isvip}}'!='0';
lock='{{$.islock}}'!='0';
type='{{$.chaptertype}}'=='1';
num=!type?'{{$.chapterid}}、':'';
if(result.match(/[一二三四五六七八九十百千万\d]+\s*章|^\d+[、\.\s]|chapter\s*\d+/i)){
num=''
}else{num=num}
result=type?'📖 '+result+' 📖':result;
v=vip?'✿ ':'';l=lock?'[此章节已锁]':'';
result=v+num+result+l;

ruleToc.chapterUrl:
$.chapterid
@js:
